/**
 * JavaScript for submission form functionality
 * 
 * @module     mod_devcode/submission_handler
 * @copyright  2024 Your Name <your@email.com>
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define(['jquery', 'mod_devcode/code_editor'], function($, CodeEditor) {
    /**
     * Initialize submission form functionality
     */
    var init = function() {
        var tabBtns = $('.tab-btn');
        var tabPanes = $('.tab-pane');
        var taskSidebar = $('#task-sidebar');
        var codeTabBtn = $('#code-tab-btn');
        var fileTabBtn = $('#file-tab-btn');
        var layout = $('.responsive-layout');
        var codeEditor = $('#id_code')[0];
        var autosaveStatus = $('#autosave-status')[0];
        var restoreSavedCodeBtn = $('#restore-saved-code')[0];
        
        // Định danh duy nhất cho code của từng bài tập
        var cmid = $('input[name="id"]').val();
        var storageName = "devcode_autosave_" + cmid;
        var savedCodeVersion = "";
        var lastSaveTime = null;
        var autosaveTimer = null;
        
        // Hiển thị sidebar mặc định cho tab code
        layout.addClass("code-tab-active");
        
        // Initialize code editor
        CodeEditor.init();
        
        // Khôi phục code đã lưu nếu có
        function initializeAutosave() {
            var savedData = localStorage.getItem(storageName);
            
            if (savedData) {
                try {
                    var parsedData = JSON.parse(savedData);
                    savedCodeVersion = parsedData.code;
                    lastSaveTime = new Date(parsedData.timestamp);
                    
                    if (savedCodeVersion !== $(codeEditor).val()) {
                        var timeAgo = formatTimeAgo(lastSaveTime);
                        $(autosaveStatus).html('<i class="fa fa-info-circle"></i> ' + 
                            'You have an autosaved version from ' + timeAgo);
                        $(autosaveStatus).attr('class', 'autosave-status autosave-exists');
                        $(restoreSavedCodeBtn).show();
                    }
                } catch (e) {
                    console.error('Error parsing saved code:', e);
                    localStorage.removeItem(storageName);
                }
            }
        }
     
        // Hiển thị thông báo đã lưu mã code
        function showSavedMessage(timestamp) {
            $(autosaveStatus).html('<i class="fa fa-check-circle"></i> ' + 
                                  'Autosaved successfully: ' + formatTimeAgo(timestamp));
            $(autosaveStatus).attr('class', 'autosave-status autosave-saved');
            
            // Ẩn thông báo sau 3 giây
            setTimeout(function() {
                $(autosaveStatus).attr('class', 'autosave-status');
            }, 3000);
        }
        
        // Format thời gian thành "x phút trước"
        function formatTimeAgo(timestamp) {
            var now = new Date();
            var diffInSeconds = Math.floor((now - timestamp) / 1000);
            
            if (diffInSeconds < 60) {
                return diffInSeconds + " seconds ago";
            } else if (diffInSeconds < 3600) {
                return Math.floor(diffInSeconds / 60) + " minutes ago";
            } else if (diffInSeconds < 86400) {
                return Math.floor(diffInSeconds / 3600) + " hours ago";
            } else {
                return Math.floor(diffInSeconds / 86400) + " days ago";
            }
        }
        
        // Lưu code vào localStorage
        function saveCodeToLocalStorage() {
            var code = $(codeEditor).val();
            var now = new Date();
            
            // Lưu code và thời gian lưu
            var dataToSave = {
                code: code,
                timestamp: now.toISOString()
            };
            
            localStorage.setItem(storageName, JSON.stringify(dataToSave));
            lastSaveTime = now;
            showSavedMessage(now);
        }
        
        // Khôi phục phiên bản đã lưu
        function restoreSavedCode() {
            if (savedCodeVersion) {
                $(codeEditor).val(savedCodeVersion);
                $(autosaveStatus).html('<i class="fa fa-check-circle"></i> Restored autosaved code');
                $(autosaveStatus).attr('class', 'autosave-status autosave-restored');
                $(restoreSavedCodeBtn).hide();
                
                // Trigger để cập nhật line numbers
                $(codeEditor).trigger('input');
            }
        }
        
        // Khởi tạo chức năng tự động lưu
        function setupAutosave() {
            // Lưu code khi người dùng thay đổi nội dung sau 1 giây không nhập
            $(codeEditor).on('input', function() {
                // Xóa timer hiện tại nếu có
                if (autosaveTimer) {
                    clearTimeout(autosaveTimer);
                }
                
                // Đặt timer mới để lưu sau 1 giây
                autosaveTimer = setTimeout(function() {
                    saveCodeToLocalStorage();
                }, 1000);
            });
            
            // Lưu code khi người dùng rời khỏi trang
            $(window).on('beforeunload', function() {
                saveCodeToLocalStorage();
            });
            
            // Khôi phục phiên bản đã lưu
            $(restoreSavedCodeBtn).on('click', function() {
                restoreSavedCode();
            });
        }
        
        // Tab switching functionality
        tabBtns.on('click', function() {
            var tabId = $(this).data('tab');
            
            // Remove active class from all buttons and panes
            tabBtns.removeClass('active');
            tabPanes.removeClass('active');
            
            // Add active class to current button and pane
            $(this).addClass('active');
            $('#' + tabId).addClass('active');
            
            // Update hidden field based on selected tab
            if (tabId === 'code-tab') {
                $('input[name="submission_method"]').val('code');
                // Hiển thị sidebar khi chọn tab code
                layout.addClass('code-tab-active');
            } else {
                $('input[name="submission_method"]').val('file');
                // Ẩn sidebar khi chọn tab file
                layout.removeClass('code-tab-active');
            }
        });
        
        // Toggle sidebar on small screens
        var toggleBtn = $('#toggle-sidebar');
        var sidebarContent = $('.sidebar-content');
        var toggleText = $('.toggle-text');
        
        if (toggleBtn.length) {
            toggleBtn.on('click', function() {
                layout.toggleClass('sidebar-visible');
                if (layout.hasClass('sidebar-visible')) {
                    toggleText.text(M.util.get_string('hideintro', 'devcode'));
                } else {
                    toggleText.text(M.util.get_string('showintro', 'devcode'));
                }
            });
        }
        
        // Initial state - show sidebar on desktop, hide on mobile
        function handleResize() {
            if (window.innerWidth < 768) {
                layout.removeClass('sidebar-visible');
            } else if (codeTabBtn.hasClass('active')) {
                layout.addClass('sidebar-visible');
            }
        }
        
        // Initial call and listen for resize
        handleResize();
        $(window).on('resize', handleResize);
        
        // Form submission handling
        var form = $('form.mform');
        
        if (form.length) {
            form.on('submit', function(e) {
                // Đảm bảo nội dung từ code editor được gửi đi
                if (codeEditor) {
                    // Nếu đang ở tab code, kiểm tra nội dung code
                    if ($('#code-tab').hasClass('active')) {
                        // Kiểm tra nếu code rỗng thì ngăn form submit và hiển thị lỗi
                        if ($(codeEditor).val().trim() === '') {
                            e.preventDefault();
                            var errorElement = $('#id_error_code');
                            if (errorElement.length) {
                                errorElement.text('Code không được để trống');
                                errorElement.show();
                            }
                            return false;
                        }
                    }
                    
                    // Lưu nội dung code vào trường code
                    var codeField = $('<input>').attr({
                        type: 'hidden',
                        name: 'code',
                        value: $(codeEditor).val()
                    });
                    form.append(codeField);
                }
                
                // Disable nút submit để tránh click nhiều lần
                var submitButton = form.find('input[type="submit"]');
                if (submitButton.length) {
                    submitButton.prop('disabled', true);
                    submitButton.val('Đang xử lý...');
                }
            });
        }
        
        // Initialize features
        initializeAutosave();
        setupAutosave();
    };

    return {
        init: init
    };
}); 